<?php
$adminPage='dashboard';$adminTitle='Operations overview';$adminPermission='dashboard.view';require __DIR__.'/../includes/admin_header.php';
$metrics=['Customers'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn(),'Verified KYC'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer' AND kyc_status='verified'")->fetchColumn(),'Pending KYC'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE kyc_status IN ('pending','under_review','needs_information')")->fetchColumn(),'Active cards'=>(int)$pdo->query("SELECT COUNT(*) FROM linked_cards WHERE status='active'")->fetchColumn()];
$flows=$pdo->query("SELECT type,COUNT(*) count,COALESCE(SUM(amount_cents),0) volume FROM financial_transactions WHERE created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY type ORDER BY volume DESC")->fetchAll();$pendingCredit=(int)$pdo->query("SELECT COUNT(*) FROM credit_applications WHERE status IN ('under_review','needs_information')")->fetchColumn();$overdue=(int)$pdo->query("SELECT COUNT(*) FROM repayment_schedule WHERE due_date<CURDATE() AND status<>'paid'")->fetchColumn();$support=(int)$pdo->query("SELECT COUNT(*) FROM support_cases WHERE status NOT IN ('resolved','closed')")->fetchColumn();$security=$pdo->query("SELECT se.*,u.email FROM security_events se LEFT JOIN users u ON u.user_id=se.user_id ORDER BY se.created_at DESC LIMIT 8")->fetchAll();
?>
<div class="metric-grid"><?php foreach($metrics as $label=>$value):?><article class="metric"><span><?=e($label)?></span><strong><?=number_format($value)?></strong></article><?php endforeach?></div><div class="app-grid"><section class="panel span-7"><div class="admin-section-head"><div><h2>30-day money movement</h2><p class="muted">Authoritative financial records.</p></div><a href="transactions.php">Open operations</a></div><?php if(!$flows):?><div class="empty">No financial activity in this period.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Type</th><th>Records</th><th>Gross amount</th></tr></thead><tbody><?php foreach($flows as $row):?><tr><td><?=e(str_replace('_',' ',$row['type']))?></td><td><?=number_format($row['count'])?></td><td class="money"><?=Money::format((int)$row['volume'])?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section><section class="panel span-5"><h2>Queues requiring attention</h2><div class="detail-grid"><div><span>Credit reviews</span><strong><?=$pendingCredit?></strong></div><div><span>Overdue schedules</span><strong><?=$overdue?></strong></div><div><span>Open support</span><strong><?=$support?></strong></div></div><p class="muted">Queue counts are live and access remains role-scoped.</p></section><section class="panel span-12"><div class="admin-section-head"><h2>Recent security events</h2><a href="audit.php">Full audit view</a></div><?php if(!$security):?><div class="empty">No security events recorded.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>Event</th><th>Customer</th><th>IP</th></tr></thead><tbody><?php foreach($security as $row):?><tr><td><?=e(formatDate($row['created_at']))?></td><td><?=e(str_replace('_',' ',$row['event_type']))?></td><td><?=e($row['email']??'System')?></td><td class="mono"><?=e($row['ip_address']??'—')?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section></div>
